<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {invoke} from '@tauri-apps/api/core'
import {executeQuery} from '@/lib/database'
import {useI18n} from '@/lib/i18n'
import {isExpired,isNearExpiry} from '@/lib/utils'
import {useSettingsStore} from '@/stores/settings'
import {useDialogKeyboard} from '@/composables/useDialogKeyboard'
const {pick,formatDateTime,formatNumber}=useI18n(),router=useRouter(),route=useRoute(),settings=useSettingsStore()
const nearExpiryDays=computed(()=>Number(settings.settings?.near_expiry_days??60))
type Batch={id:string;product_id:string;name:string;sku:string;batch_number:string;expiry_date:string;quantity_in_stock:number;held:number}
type Hold={id:string;batch_id:string;quantity:number;reason:string;status:string;created_at:string;created_by_name:string;name:string;batch_number:string;expiry_date:string;resolved_by_name:string|null;resolution_notes:string|null}
const batches=ref<Batch[]>([]),holds=ref<Hold[]>([]),tab=ref('batches'),query=ref(''),filter=ref('near'),selectedId=ref(String(route.query.batch||'')),quantity=ref(1),reason=ref(''),requestId=ref(crypto.randomUUID()),busy=ref(false),error=ref(''),notice=ref(''),selectedHold=ref<Hold|null>(null),resolution=ref('written_off'),resolutionNotes=ref(''),dialog=ref<HTMLElement|null>(null)
useDialogKeyboard(dialog,()=>{if(!busy.value)selectedHold.value=null})
const selected=computed(()=>batches.value.find(b=>b.id===selectedId.value))
const visible=computed(()=>batches.value.filter(b=>`${b.name} ${b.sku} ${b.batch_number}`.toLowerCase().includes(query.value.toLowerCase())&&(filter.value==='all'||(filter.value==='held'?b.held>0:filter.value==='expired'?isExpired(b.expiry_date):isExpired(b.expiry_date)||isNearExpiry(b.expiry_date,nearExpiryDays.value)))))
onMounted(async()=>{await settings.loadSettings();await load()})
async function load(){error.value='';try{[batches.value,holds.value]=await Promise.all([executeQuery<Batch>("SELECT b.*,p.name,p.sku,COALESCE((SELECT SUM(quantity) FROM batch_holds h WHERE h.batch_id=b.id AND h.status='held'),0) AS held FROM product_batches b JOIN products p ON p.id=b.product_id WHERE p.deleted_at IS NULL AND (b.quantity_in_stock>0 OR EXISTS(SELECT 1 FROM batch_holds h WHERE h.batch_id=b.id AND h.status='held')) ORDER BY b.expiry_date,p.name"),executeQuery<Hold>("SELECT h.*,p.name,b.batch_number,b.expiry_date,u.full_name AS created_by_name,a.full_name AS resolved_by_name FROM batch_holds h JOIN product_batches b ON b.id=h.batch_id JOIN products p ON p.id=b.product_id JOIN users u ON u.id=h.created_by LEFT JOIN users a ON a.id=h.resolved_by ORDER BY h.created_at DESC")]);if(selectedId.value)filter.value='all'}catch(e){error.value=String(e)}}
function adjustment(action:string){if(!selected.value)return;void router.push({path:'/stock-adjustments/new',query:{batch:selected.value.id,reason:action}})}
async function quarantine(){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await invoke('hold_batch',{request:{requestId:requestId.value,batchId:selectedId.value,quantity:Number(quantity.value),reason:reason.value}});requestId.value=crypto.randomUUID();quantity.value=1;reason.value='';notice.value=pick('Units quarantined and excluded from sale immediately.','اکائیاں قرنطینہ میں منتقل ہوئیں اور فوری طور پر فروخت سے خارج ہیں۔');await load()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function resolve(){if(!selectedHold.value||busy.value)return;busy.value=true;error.value='';try{await invoke('resolve_batch_hold',{id:selectedHold.value.id,action:resolution.value,notes:resolutionNotes.value});selectedHold.value=null;await load()}catch(e){error.value=String(e)}finally{busy.value=false}}
</script>
<template>
 <div class="tool-terminal finance-terminal"><header class="tool-header"><div><h1>{{pick('Expiry & Quarantine Actions','میعاد اور قرنطینہ کی کارروائیاں')}}</h1><p>{{pick('Manager-approved stock protection and auditable resolutions','منیجر کی مجاز اسٹاک حفاظت اور قابلِ پڑتال تصفیے')}}</p></div><button @click="load">{{pick('Refresh','تازہ کریں')}}</button></header>
 <div class="commercial-tabs"><button :aria-pressed="tab==='batches'" @click="tab='batches'">{{pick('Batch actions','بیچ کی کارروائیاں')}}</button><button :aria-pressed="tab==='holds'" @click="tab='holds'">{{pick('Quarantine audit','قرنطینہ ریکارڈ')}}</button></div><p v-if="error" class="commercial-error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
 <div v-if="tab==='batches'" class="commercial-split"><section class="commercial-main"><div class="commercial-filters"><input v-model="query" type="search" :placeholder="pick('Product, SKU or batch','مصنوعات، کوڈ یا بیچ')"/><select v-model="filter" :aria-label="pick('Stock filter','اسٹاک فلٹر')"><option value="near">{{pick('Expired / next','میعاد ختم / اگلے')}} {{formatNumber(nearExpiryDays)}} {{pick('days','دن')}}</option><option value="expired">{{pick('Expired only','صرف میعاد ختم')}}</option><option value="held">{{pick('Has quarantined units','قرنطینہ اکائیاں موجود')}}</option><option value="all">{{pick('All batches','تمام بیچ')}}</option></select></div><div class="commercial-table-scroll"><table><thead><tr><th>{{pick('Product / batch','مصنوعات / بیچ')}}</th><th>{{pick('Expiry','میعاد')}}</th><th>{{pick('Outside quarantine','قرنطینہ سے باہر')}}</th><th>{{pick('Quarantined units','قرنطینہ اکائیاں')}}</th><th></th></tr></thead><tbody><tr v-for="b in visible" :key="b.id"><td>{{b.name}}<small>{{b.batch_number}} · {{b.sku}}</small></td><td>{{b.expiry_date}}<small v-if="isExpired(b.expiry_date)" class="stock-badge expired">{{pick('Expired — cannot sell','میعاد ختم — فروخت منع')}}</small><small v-else-if="isNearExpiry(b.expiry_date,nearExpiryDays)" class="stock-badge near">{{pick('Near expiry','قریب المیعاد')}}</small></td><td>{{b.quantity_in_stock}}</td><td><strong v-if="b.held" class="stock-badge held">{{pick('Quarantined','قرنطینہ')}}: {{b.held}}</strong><span v-else>0</span></td><td><button @click="selectedId=b.id">{{pick('Select','منتخب کریں')}}</button></td></tr><tr v-if="!visible.length"><td colspan="5" class="commercial-empty">{{pick('No batches match.','کوئی بیچ نہیں ملا۔')}}</td></tr></tbody></table></div><footer class="tool-summary"><small>{{pick('Available units exclude quarantine; expired units are always blocked by POS.','دستیاب تعداد میں قرنطینہ شامل نہیں؛ میعاد ختم اکائیاں POS میں ہمیشہ ممنوع ہیں۔')}}</small></footer></section>
 <aside class="commercial-dock"><h2>{{pick('Batch actions','بیچ کی کارروائیاں')}}</h2><form @submit.prevent="quarantine"><label>{{pick('Product / batch','مصنوعات / بیچ')}}<select v-model="selectedId" required><option value="">{{pick('Choose batch','بیچ منتخب کریں')}}</option><option v-for="b in batches" :key="b.id" :value="b.id">{{b.name}} · {{b.batch_number}}</option></select></label><p v-if="selected">{{pick('Outside quarantine','قرنطینہ سے باہر')}}: {{selected.quantity_in_stock}} · {{pick('Held','قرنطینہ')}}: {{selected.held}}</p><label>{{pick('Units to quarantine','قرنطینہ کی اکائیاں')}}<input v-model.number="quantity" type="number" min="1" :max="selected?.quantity_in_stock||0" step="1" required/></label><label>{{pick('Reason','وجہ')}}<textarea v-model="reason" maxlength="500" required/></label><button class="bg-primary" :disabled="busy||!selected||!selected.quantity_in_stock">{{pick('Quarantine now','اب قرنطینہ کریں')}}</button><p class="commercial-hint">{{pick('Quarantine is an immediate authorized hold. It does not destroy stock or change supplier balances.','قرنطینہ فوری مجاز پابندی ہے۔ یہ اسٹاک تلف نہیں کرتا یا سپلائر کا بقایا نہیں بدلتا۔')}}</p></form><hr/><button :disabled="!selected||!selected.quantity_in_stock" @click="adjustment('expired')">{{pick('Write-off → approval','تلفی ← منظوری')}}</button><button :disabled="!selected||!selected.quantity_in_stock" @click="adjustment('return_to_supplier')">{{pick('Return to supplier → approval','سپلائر کو واپسی ← منظوری')}}</button><p class="commercial-hint">{{pick('For available units, write-offs and supplier returns use the existing adjustment approval. Resolve held units from Quarantine audit. Record supplier credits separately after confirmation.','دستیاب اکائیوں کی تلفی اور سپلائر واپسی موجودہ منظوری سے ہوتی ہے۔ قرنطینہ اکائیوں کا تصفیہ ریکارڈ سے کریں۔ تصدیق کے بعد سپلائر کریڈٹ الگ درج کریں۔')}}</p></aside></div>
 <div v-else class="commercial-table-scroll"><table><thead><tr><th>{{pick('Product / batch','مصنوعات / بیچ')}}</th><th>{{pick('Quantity / reason','تعداد / وجہ')}}</th><th>{{pick('Held by / date','روکنے والا / تاریخ')}}</th><th>{{pick('Status / resolution','حیثیت / تصفیہ')}}</th><th></th></tr></thead><tbody><tr v-for="h in holds" :key="h.id"><td>{{h.name}}<small>{{h.batch_number}}</small></td><td>{{h.quantity}}<small>{{h.reason}}</small></td><td>{{h.created_by_name}}<small>{{formatDateTime(h.created_at)}}</small></td><td>{{h.status}}<small>{{h.resolved_by_name}} {{h.resolution_notes}}</small></td><td><button v-if="h.status==='held'" @click="selectedHold=h;resolution='written_off';resolutionNotes=''">{{pick('Resolve hold','قرنطینہ کا تصفیہ')}}</button></td></tr></tbody></table></div>
 <div v-if="selectedHold" class="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4"><form ref="dialog" class="commercial-dialog" role="dialog" aria-modal="true" tabindex="-1" :aria-label="pick('Resolve quarantine','قرنطینہ کا تصفیہ')" @submit.prevent="resolve"><h2>{{selectedHold.name}} · {{selectedHold.batch_number}} · {{selectedHold.quantity}}</h2><label>{{pick('Resolution','تصفیہ')}}<select v-model="resolution"><option value="released">{{pick('Release for sale (unexpired only)','فروخت کے لیے جاری کریں (درست میعاد)')}}</option><option value="written_off">{{pick('Confirm destruction / write-off','تلفی کی تصدیق')}}</option><option value="returned">{{pick('Confirm physical return to supplier','سپلائر کو حقیقی واپسی کی تصدیق')}}</option></select></label><label>{{pick('Reason / return reference','وجہ / واپسی حوالہ')}}<textarea v-model="resolutionNotes" required maxlength="500"/></label><p>{{pick('This resolves the entire hold. Disposal and supplier returns do not reduce available stock again or create supplier credit.','یہ پورے قرنطینہ کا تصفیہ ہے۔ تلفی یا واپسی دوبارہ اسٹاک کم نہیں کرتی اور سپلائر کریڈٹ نہیں بناتی۔')}}</p><p v-if="error" role="alert" class="commercial-error">{{error}}</p><div><button type="button" :disabled="busy" @click="selectedHold=null">{{pick('Cancel','منسوخ')}}</button> <button class="bg-primary" :disabled="busy">{{pick('Confirm resolution','تصفیہ کی تصدیق')}}</button></div></form></div>
 </div>
</template>
